<?php

/**
 * Subject store for the admin portal (MySQL).
 *
 * Used by subjects.php (add / edit / view) and schedule.php (subject dropdown).
 *
 * A subject has: id, code, title, description.
 * The code is a random 5-digit number generated by the server (for Moodle),
 * and it never changes once created.
 *
 * Table: see subjects.sql
 */

// Shared connection: htdocs/functions/db.php (set your database login there)
require_once __DIR__ . "/../../functions/db.php";

const SUBJECT_CODE_DIGITS = 5;

function subjects_db(): PDO
{
    return db_connect();
}

/** Cast a database row to the shape the pages use. */
function subjects_row(array $row): array
{
    return [
        "id"          => (int) $row["id"],
        "code"        => (string) $row["code"],
        "title"       => (string) $row["title"],
        "description" => (string) ($row["description"] ?? ""),
    ];
}

/** Every subject as a list of rows, sorted by code. */
function subjects_all(): array
{
    $stmt = subjects_db()->query("SELECT id, code, title, description FROM subjects ORDER BY code ASC");
    return array_map("subjects_row", $stmt->fetchAll());
}

/** One subject by id, or null if it does not exist. */
function subject_find(int $id): ?array
{
    $stmt = subjects_db()->prepare("SELECT id, code, title, description FROM subjects WHERE id = :id");
    $stmt->execute([":id" => $id]);
    $row = $stmt->fetch();
    return $row ? subjects_row($row) : null;
}

/**
 * Insert a new subject with a fresh random code.
 * Returns the generated code. Retries if the random code is already taken.
 */
function subject_create(array $clean): string
{
    $stmt = subjects_db()->prepare(
        "INSERT INTO subjects (code, title, description) VALUES (:code, :title, :description)"
    );

    for ($try = 0; $try < 50; $try++) {
        $code = subject_generate_code();
        try {
            $stmt->execute([
                ":code"        => $code,
                ":title"       => $clean["title"],
                ":description" => $clean["description"],
            ]);
            return $code;
        } catch (PDOException $e) {
            // 1062 = duplicate entry (code already used): try another code
            if ((int) ($e->errorInfo[1] ?? 0) !== 1062) {
                throw $e;
            }
        }
    }
    throw new RuntimeException("Could not find a free subject code.");
}

/** Update title and description only (the code never changes). */
function subject_update(int $id, array $clean): void
{
    $stmt = subjects_db()->prepare(
        "UPDATE subjects SET title = :title, description = :description WHERE id = :id"
    );
    $stmt->execute([
        ":title"       => $clean["title"],
        ":description" => $clean["description"],
        ":id"          => $id,
    ]);
}

/** The shape schedule.php expects: [id => ["code" => ..., "title" => ...]]. */
function subjects_for_schedule(): array
{
    $out = [];
    foreach (subjects_all() as $row) {
        $out[$row["id"]] = ["code" => $row["code"], "title" => $row["title"]];
    }
    return $out;
}

/** A random 5-digit code (10000-99999). Uniqueness is enforced by the database. */
function subject_generate_code(): string
{
    return (string) random_int(10 ** (SUBJECT_CODE_DIGITS - 1), 10 ** SUBJECT_CODE_DIGITS - 1);
}

/**
 * Validate posted subject data (title and description only; the code is generated).
 * Returns [$errors, $clean]; $clean is only meaningful when $errors is empty.
 */
function subject_validate(array $input): array
{
    $errors = [];
    $clean = [
        "title" => preg_replace('/\s+/', " ", trim((string) ($input["title"] ?? ""))),
        "description" => trim((string) ($input["description"] ?? "")),
    ];

    if ($clean["title"] === "") {
        $errors[] = "Enter a subject title.";
    } elseif (mb_strlen($clean["title"]) > 120) {
        $errors[] = "The subject title must be 120 characters or fewer.";
    }

    if (mb_strlen($clean["description"]) > 300) {
        $errors[] = "The description must be 300 characters or fewer.";
    }

    return [$errors, $clean];
}
